# RGB-derived: docs/play_xylophone/applied_values.json (rgb_derived_values).
# RGB geometry updates generated by --run-geometry-fitting.
# Evidence: docs/play_xylophone/geometry_fit.json
"""Policy for play_Xylophone using RGB, calibration and proprioception.

1. Rainbow key segmentation + robust straight-row fit of the key centroids in cam_head at Step 0.
2. Pink spherical beat-head detection + 360-deg radial matched-filter shaft/stand estimation.
3. Close-up cam_left_wrist shaft centerline refinement at pre-grasp hover (0 extra actions).
4. Proprioceptive + background-subtracted fixed-camera visual lift verification and offset tracking.
5. Continuous wrist joint (j5) strike planning and high-clearance inter-key lifts."""
import math
import numpy as np
_MALLET_HEAD_Z = 0.778  # +/-0.002, sphere center in world z.
_TABLE_Z = 0.765  # +/-0.002, fitted support near the observed instrument.
# Geometry fit. docs/play_xylophone/geometry_fit.json
_KEY_PLANE_Z = 0.7861
# The grasp distance starts at the head CENTER: use the observable center-to-butt
# span, not the unobservable material endpoint buried within the mallet head.
_SHAFT_YMAX_DEFAULT = 0.200  # +/-0.002, shaft_observable_spans.butt_to_head_center.
_ROW_SPACING_DEFAULT = 0.043  # +/-0.0015, adjacent key-axis spacing.
_KEY_WIDTH_DEFAULT = 0.0377
_KEY_LENGTH_DEFAULT = 0.17515

def _wrap_deg(angle):
    return float((angle + 180.0) % 360.0 - 180.0)

def _pixel_to_world_at_z(meta, row, col, z_plane):
    """Intersect a camera pixel ray (row, col) with horizontal world plane z = z_plane."""
    k = np.asarray(meta['intrinsic_matrix'], dtype=float)
    t = np.asarray(meta['extrinsic_matrix'], dtype=float)
    ray_cam = np.linalg.solve(k, np.array([float(col), float(row), 1.0], dtype=float))
    ray_cam = ray_cam * np.array([1.0, -1.0, -1.0], dtype=float)
    ray_world = t[:3, :3] @ ray_cam
    origin = t[:3, 3]
    if abs(float(ray_world[2])) < 1e-08:
        return None
    s = (float(z_plane) - float(origin[2])) / float(ray_world[2])
    if s <= 0.0:
        return None
    return origin + s * ray_world

def _world_to_pixel(meta, pts_world):
    """Project (N, 3) or (3,) world points into (row, col) pixel coordinates."""
    k = np.asarray(meta['intrinsic_matrix'], dtype=float)
    t = np.asarray(meta['extrinsic_matrix'], dtype=float)
    r_c2w = t[:3, :3]
    origin = t[:3, 3]
    pts = np.asarray(pts_world, dtype=float)
    single = pts.ndim == 1
    if single:
        pts = pts.reshape(1, 3)
    d = pts - origin.reshape(1, 3)
    p_cam = d @ r_c2w
    depth = -p_cam[:, 2]
    safe_depth = np.where(depth > 0.0001, depth, 1.0)
    u = p_cam[:, 0] / safe_depth
    v = -p_cam[:, 1] / safe_depth
    cols = k[0, 0] * u + k[0, 2]
    rows = k[1, 1] * v + k[1, 2]
    rc = np.column_stack((rows, cols))
    if single:
        return (rc[0], bool(depth[0] > 0.0001))
    return (rc, depth > 0.0001)

def _compute_hsv_and_stats(img):
    """Compute float RGB, HSV (H in [0, 360), S in [0, 1], V in [0, 255]), and chroma."""
    arr = np.asarray(img, dtype=float)
    r = arr[:, :, 0]
    g = arr[:, :, 1]
    b = arr[:, :, 2]
    max_c = np.maximum(np.maximum(r, g), b)
    min_c = np.minimum(np.minimum(r, g), b)
    chroma = max_c - min_c
    sat = chroma / np.maximum(max_c, 1.0)
    hue = np.zeros_like(max_c)
    mask_c = chroma > 0.001
    idx_r = mask_c & (max_c == r)
    idx_g = mask_c & (max_c == g) & ~idx_r
    idx_b = mask_c & ~idx_r & ~idx_g
    hue[idx_r] = 60.0 * ((g[idx_r] - b[idx_r]) / chroma[idx_r]) % 360.0
    hue[idx_g] = 60.0 * ((b[idx_g] - r[idx_g]) / chroma[idx_g] + 2.0)
    hue[idx_b] = 60.0 * ((r[idx_b] - g[idx_b]) / chroma[idx_b] + 4.0)
    return (r, g, b, hue, sat, max_c, min_c, chroma)

def _connected_components(mask, min_area=15):
    """Pure-NumPy/Python 8-connected components returning list of dicts sorted by area desc."""
    mask_bool = np.asarray(mask, dtype=bool)
    h, w = mask_bool.shape
    visited = np.zeros((h, w), dtype=bool)
    ys, xs = np.nonzero(mask_bool)
    comps = []
    for r0, c0 in zip(ys.tolist(), xs.tolist()):
        if visited[r0, c0]:
            continue
        visited[r0, c0] = True
        q_r = [r0]
        q_c = [c0]
        head = 0
        while head < len(q_r):
            cr = q_r[head]
            cc = q_c[head]
            head += 1
            r_min = cr - 1 if cr > 0 else 0
            r_max = cr + 1 if cr + 1 < h else h - 1
            c_min = cc - 1 if cc > 0 else 0
            c_max = cc + 1 if cc + 1 < w else w - 1
            for nr in range(r_min, r_max + 1):
                for nc in range(c_min, c_max + 1):
                    if mask_bool[nr, nc] and (not visited[nr, nc]):
                        visited[nr, nc] = True
                        q_r.append(nr)
                        q_c.append(nc)
        area = len(q_r)
        if area < min_area:
            continue
        pts_r = np.asarray(q_r, dtype=float)
        pts_c = np.asarray(q_c, dtype=float)
        r_lo, r_hi = np.quantile(pts_r, (0.05, 0.95))
        c_lo, c_hi = np.quantile(pts_c, (0.05, 0.95))
        center_r = 0.5 * float(np.mean(pts_r)) + 0.25 * float(r_lo + r_hi)
        center_c = 0.5 * float(np.mean(pts_c)) + 0.25 * float(c_lo + c_hi)
        comps.append({'area': area, 'row': center_r, 'col': center_c, 'r_min': int(np.min(pts_r)), 'r_max': int(np.max(pts_r)), 'c_min': int(np.min(pts_c)), 'c_max': int(np.max(pts_c)), 'rows': pts_r, 'cols': pts_c})
    comps.sort(key=lambda x: x['area'], reverse=True)
    return comps

def _pixels_to_world_at_z(meta, rows, cols, z_plane):
    """Intersect many pixel rays with the horizontal plane z = z_plane; returns (N, 2) XY and a validity mask."""
    k = np.asarray(meta['intrinsic_matrix'], dtype=float)
    t = np.asarray(meta['extrinsic_matrix'], dtype=float)
    rows = np.asarray(rows, dtype=float).reshape(-1)
    cols = np.asarray(cols, dtype=float).reshape(-1)
    pix = np.vstack((cols, rows, np.ones_like(rows)))
    rays = np.linalg.solve(k, pix) * np.array([[1.0], [-1.0], [-1.0]])
    rays_w = t[:3, :3] @ rays
    origin = t[:3, 3]
    dz = rays_w[2]
    ok = np.abs(dz) > 1e-08
    s = np.where(ok, (float(z_plane) - float(origin[2])) / np.where(ok, dz, 1.0), -1.0)
    ok &= s > 0.0
    xy = origin[:2].reshape(2, 1) + s.reshape(1, -1) * rays_w[:2]
    return (xy.T, ok)

def _fit_key_row(detected_keys):
    """Robustly fit the straight key row: centre of key k = origin + k * step (XY, metres).

    Candidate rows come from pairs of observed keys at least two indices apart whose
    image columns increase with the key index; the candidate with the most keys within
    1.6 cm (then the smallest squared error) is refined by least squares on those keys.
    Returns (origin_xy, step_xy, inlier_indices, rms_m) or None.
    """
    valid_indices = sorted(detected_keys.keys())
    best_inliers = []
    best_err = 1000000000.0
    for i_idx in range(len(valid_indices)):
        for j_idx in range(i_idx + 1, len(valid_indices)):
            ki = valid_indices[i_idx]
            kj = valid_indices[j_idx]
            if kj - ki < 2:
                continue
            if detected_keys[ki]['col'] >= detected_keys[kj]['col']:
                continue
            p_i = np.asarray(detected_keys[ki]['world_xyz'][:2], dtype=float)
            p_j = np.asarray(detected_keys[kj]['world_xyz'][:2], dtype=float)
            step = (p_j - p_i) / float(kj - ki)
            if float(np.linalg.norm(step)) <= 0.0:
                continue
            origin = p_i - float(ki) * step
            inliers = []
            err_sum = 0.0
            for kk in valid_indices:
                dist = float(np.linalg.norm(origin + float(kk) * step - np.asarray(detected_keys[kk]['world_xyz'][:2], dtype=float)))
                if dist < 0.016:
                    inliers.append(kk)
                    err_sum += dist * dist
            if len(inliers) > len(best_inliers) or (len(inliers) == len(best_inliers) and err_sum < best_err):
                best_inliers = inliers
                best_err = err_sum
    if len(best_inliers) < 2:
        return None
    idx = np.asarray(best_inliers, dtype=float)
    pts = np.array([detected_keys[kk]['world_xyz'][:2] for kk in best_inliers], dtype=float)
    design = np.column_stack((np.ones_like(idx), idx))
    coef, _, _, _ = np.linalg.lstsq(design, pts, rcond=None)
    origin = coef[0]
    step = coef[1]
    if float(np.linalg.norm(step)) <= 0.0:
        return None
    rms = math.sqrt(float(np.mean(np.sum((design @ coef - pts) ** 2, axis=1))))
    return (origin, step, best_inliers, rms)

def _measure_key_extents(meta_head, detected_keys, indices, row_dir):
    """Measure each observed key's width along the row and length across it from its colour pixels.

    Returns (half_width_m, half_length_m[8]): one half width (median over observed keys) and a
    per-key half length from a straight-line fit of the observed lengths against the key index.
    """
    row_dir = np.asarray(row_dir, dtype=float) / max(float(np.linalg.norm(row_dir)), 1e-09)
    row_nrm = np.array([-row_dir[1], row_dir[0]], dtype=float)
    widths = []
    lengths = []
    for kk in indices:
        comp = detected_keys[kk]['comp']
        xy, ok = _pixels_to_world_at_z(meta_head, comp['rows'], comp['cols'], _KEY_PLANE_Z)
        if int(np.sum(ok)) < 20:
            continue
        rel = xy[ok] - np.asarray(detected_keys[kk]['world_xyz'][:2], dtype=float).reshape(1, 2)
        along = rel @ row_dir
        across = rel @ row_nrm
        a_lo, a_hi = np.quantile(along, (0.02, 0.98))
        c_lo, c_hi = np.quantile(across, (0.02, 0.98))
        widths.append(float(a_hi - a_lo))
        lengths.append((float(kk), float(c_hi - c_lo)))
    half_w = 0.5 * float(np.median(widths)) if widths else 0.5 * _KEY_WIDTH_DEFAULT
    if len(lengths) >= 2:
        arr = np.asarray(lengths, dtype=float)
        slope, intercept = np.polyfit(arr[:, 0], arr[:, 1], 1)
        half_l = [0.5 * float(np.clip(intercept + slope * kk, 0.5 * _KEY_LENGTH_DEFAULT, 2.0 * _KEY_LENGTH_DEFAULT)) for kk in range(8)]
    elif len(lengths) == 1:
        half_l = [0.5 * lengths[0][1]] * 8
    else:
        half_l = [0.5 * _KEY_LENGTH_DEFAULT] * 8
    return (half_w, half_l)

def _detect_xylophone(robo, img_head, meta_head):
    """Segment the 8 rainbow xylophone keys in cam_head and fit the straight key row through their centroids."""
    h, w, _ = img_head.shape
    r, g, b, hue, sat, max_c, _, chroma = _compute_hsv_and_stats(img_head)
    rows_grid, cols_grid = np.indices((h, w))
    roi = (rows_grid >= 80) & (rows_grid <= 360) & (cols_grid >= 70) & (cols_grid <= 570)
    roi &= ~((rows_grid >= 245) & (cols_grid <= 172))
    roi &= ~((rows_grid >= 245) & (cols_grid >= 468))
    vivid = roi & (sat >= 0.46) & (max_c >= 150.0) & (chroma >= 80.0)
    key_masks = [vivid & ((hue >= 325.0) | (hue < 14.0)) & (r > 190.0) & (g < 95.0) & (b > 50.0) & (r - g > 120.0), vivid & (hue >= 29.0) & (hue < 49.0) & (r > 210.0) & (g > 122.0) & (b < 82.0) & (r - b > 145.0), vivid & (hue >= 49.0) & (hue < 76.0) & (r > 195.0) & (g > 195.0) & (b < 90.0), vivid & (hue >= 82.0) & (hue < 168.0) & (g > 165.0) & (g - r > 85.0) & (g - b > 75.0), vivid & (hue >= 178.0) & (hue < 210.5) & (b > 185.0) & (g > 130.0) & (r < 90.0), vivid & (hue >= 210.5) & (hue < 250.0) & (b > 175.0) & (g <= 150.0) & (r < 85.0), vivid & (hue >= 252.0) & (hue < 292.0) & (b > 175.0) & (r > 110.0) & (g < 90.0), vivid & (hue >= 292.0) & (hue < 325.0) & (r > 185.0) & (b > 155.0) & (g < 90.0)]
    detected_keys = {}
    xylo_exclusion = np.zeros((h, w), dtype=bool)
    for k_idx, kmask in enumerate(key_masks):
        min_a = 280 if k_idx == 0 else 160
        comps = _connected_components(kmask, min_area=min_a)
        if not comps:
            continue
        chosen = None
        for comp in comps:
            height_px = comp['r_max'] - comp['r_min'] + 1
            if k_idx == 0 and height_px < 32:
                continue
            chosen = comp
            break
        if chosen is None:
            continue
        pt_w = _pixel_to_world_at_z(meta_head, chosen['row'], chosen['col'], _KEY_PLANE_Z)
        if pt_w is None:
            continue
        detected_keys[k_idx] = {'comp': chosen, 'world_xyz': pt_w, 'row': chosen['row'], 'col': chosen['col']}
        r0 = max(0, chosen['r_min'] - 10)
        r1 = min(h, chosen['r_max'] + 11)
        c0 = max(0, chosen['c_min'] - 10)
        c1 = min(w, chosen['c_max'] + 11)
        xylo_exclusion[r0:r1, c0:c1] = True
    valid_indices = sorted(detected_keys.keys())
    if len(valid_indices) < 5:
        try:
            sight = robo.locate('the colorful xylophone', camera='cam_head')
            if getattr(sight, 'found', False) and getattr(sight, 'center_xyz', None) is not None:
                c_xyz = np.asarray(sight.center_xyz, dtype=float)
                axis_deg = float(getattr(sight, 'long_axis_deg', 0.0) or 0.0)
                yaw_rad = math.radians(axis_deg + 180.0)
                x_pos = np.array([float(c_xyz[0]), float(c_xyz[1]), _TABLE_Z], dtype=float)
                x_quat = np.array([math.cos(0.5 * yaw_rad), 0.0, 0.0, math.sin(0.5 * yaw_rad)], dtype=float)
                step = _ROW_SPACING_DEFAULT * np.array([math.cos(math.radians(axis_deg)), math.sin(math.radians(axis_deg))], dtype=float)
                key_xy = np.array([c_xyz[:2] + (float(kk) - 3.5) * step for kk in range(8)], dtype=float)
                return {'x_pos': x_pos, 'x_quat': x_quat, 'key_xy': key_xy, 'obs_keys': {}, 'xylo_exclusion': xylo_exclusion}
        except Exception:
            pass
        return None
    row_fit = _fit_key_row(detected_keys)
    if row_fit is None:
        return None
    origin, step, best_inliers, rms = row_fit
    if len(best_inliers) < 5 or rms > 0.015:
        return None
    key_xy = np.array([origin + float(kk) * step for kk in range(8)], dtype=float)
    row_mid = 0.5 * (key_xy[0] + key_xy[7])
    row_yaw = math.atan2(-float(step[1]), -float(step[0]))
    x_pos = np.array([float(row_mid[0]), float(row_mid[1]), _TABLE_Z], dtype=float)
    x_quat = np.array([math.cos(0.5 * row_yaw), 0.0, 0.0, math.sin(0.5 * row_yaw)], dtype=float)
    row_dir = step / float(np.linalg.norm(step))
    row_nrm = np.array([-row_dir[1], row_dir[0]], dtype=float)
    half_w, half_l = _measure_key_extents(meta_head, detected_keys, best_inliers, row_dir)
    for kk in range(8):
        corners = []
        for sa in (-1.0, 1.0):
            for sc in (-1.0, 1.0):
                xy = key_xy[kk] + sa * half_w * row_dir + sc * half_l[kk] * row_nrm
                corners.append([float(xy[0]), float(xy[1]), _KEY_PLANE_Z])
        rc_pts, valid_p = _world_to_pixel(meta_head, np.asarray(corners, dtype=float))
        if np.all(valid_p):
            r0 = max(0, int(np.min(rc_pts[:, 0])) - 8)
            r1 = min(h, int(np.max(rc_pts[:, 0])) + 9)
            c0 = max(0, int(np.min(rc_pts[:, 1])) - 8)
            c1 = min(w, int(np.max(rc_pts[:, 1])) + 9)
            xylo_exclusion[r0:r1, c0:c1] = True
    obs_keys = {}
    for kk in best_inliers:
        obs_keys[kk] = detected_keys[kk]['world_xyz']
    return {'x_pos': x_pos, 'x_quat': x_quat, 'key_xy': key_xy, 'obs_keys': obs_keys, 'xylo_exclusion': xylo_exclusion}

def _get_key_target_xyz(xylo_info, key_idx):
    """Compute the key centre XYZ and strike height from the fitted key row and the observed key."""
    row_xy = np.asarray(xylo_info['key_xy'][key_idx], dtype=float)
    b_model = np.array([float(row_xy[0]), float(row_xy[1]), _KEY_PLANE_Z], dtype=float)
    obs_keys = xylo_info.get('obs_keys', {})
    if key_idx in obs_keys:
        obs_pt = np.asarray(obs_keys[key_idx], dtype=float)
        if float(np.linalg.norm(obs_pt[:2] - b_model[:2])) < 0.01:
            b_model = np.array([0.5 * float(b_model[0]) + 0.5 * float(obs_pt[0]), 0.5 * float(b_model[1]) + 0.5 * float(obs_pt[1]), float(obs_pt[2])], dtype=float)
    return (b_model, float(b_model[2]))

def _score_shaft_ray_in_head(img_head, meta_head, m_pos_cand, theta_rad):
    """Score a candidate 3D mallet shaft angle theta_rad starting from m_pos_cand in cam_head."""
    h, w, _ = img_head.shape
    u = np.array([math.cos(theta_rad), math.sin(theta_rad), 0.0], dtype=float)
    u_perp = np.array([-math.sin(theta_rad), math.cos(theta_rad), 0.0], dtype=float)
    d_near = np.linspace(0.018, 0.082, 22)
    pts_c = m_pos_cand.reshape(1, 3) + d_near.reshape(-1, 1) * u.reshape(1, 3)
    pts_l = pts_c + 0.013 * u_perp.reshape(1, 3)
    pts_r = pts_c - 0.013 * u_perp.reshape(1, 3)
    rc_c, val_c = _world_to_pixel(meta_head, pts_c)
    rc_l, val_l = _world_to_pixel(meta_head, pts_l)
    rc_r, val_r = _world_to_pixel(meta_head, pts_r)
    near_scores = []
    wood_hits = 0
    for idx in range(len(d_near)):
        if not (val_c[idx] and val_l[idx] and val_r[idx]):
            continue
        rc, cc = (int(round(rc_c[idx, 0])), int(round(rc_c[idx, 1])))
        rl, cl = (int(round(rc_l[idx, 0])), int(round(rc_l[idx, 1])))
        rr, cr = (int(round(rc_r[idx, 0])), int(round(rc_r[idx, 1])))
        if not (0 <= rc < h and 0 <= cc < w and (0 <= rl < h) and (0 <= cl < w) and (0 <= rr < h) and (0 <= cr < w)):
            continue
        pc = img_head[rc, cc].astype(float)
        pl = img_head[rl, cl].astype(float)
        pr = img_head[rr, cr].astype(float)
        is_wood = pc[0] > 175.0 and pc[1] > 125.0 and (pc[2] > 75.0) and (pc[0] >= pc[1] - 5.0)
        if is_wood:
            wood_hits += 1
        gb_c = pc[1] + pc[2]
        gb_bg = 0.5 * (pl[1] + pl[2] + pr[1] + pr[2])
        near_scores.append(gb_c - gb_bg)
    if len(near_scores) < 10 or wood_hits < 7:
        return (-1000000.0, 0.1)
    wood_near_score = float(np.mean(near_scores)) * (float(wood_hits) / float(len(near_scores)))
    d_stand_grid = np.linspace(0.068, 0.132, 20)
    pts_s = m_pos_cand.reshape(1, 3) + d_stand_grid.reshape(-1, 1) * u.reshape(1, 3)
    rc_s, val_s = _world_to_pixel(meta_head, pts_s)
    stand_vals = []
    best_d_stand = 0.1
    best_s_val = -1000000.0
    for idx, d_val in enumerate(d_stand_grid):
        if not val_s[idx]:
            continue
        rs, cs = (int(round(rc_s[idx, 0])), int(round(rc_s[idx, 1])))
        if not (0 <= rs < h and 0 <= cs < w):
            continue
        if rs >= 278 and cs <= 116:
            continue
        ps = img_head[rs, cs].astype(float)
        s_val = ps[2] - 0.35 * ps[0]
        stand_vals.append(s_val)
        if s_val > best_s_val:
            best_s_val = s_val
            best_d_stand = float(d_val)
    stand_score = max(0.0, float(np.max(stand_vals)) if stand_vals else 0.0)
    d_far = np.linspace(0.128, 0.192, 16)
    pts_fc = m_pos_cand.reshape(1, 3) + d_far.reshape(-1, 1) * u.reshape(1, 3)
    pts_fl = pts_fc + 0.013 * u_perp.reshape(1, 3)
    pts_fr = pts_fc - 0.013 * u_perp.reshape(1, 3)
    rc_fc, val_fc = _world_to_pixel(meta_head, pts_fc)
    rc_fl, val_fl = _world_to_pixel(meta_head, pts_fl)
    rc_fr, val_fr = _world_to_pixel(meta_head, pts_fr)
    far_scores = []
    for idx in range(len(d_far)):
        if not (val_fc[idx] and val_fl[idx] and val_fr[idx]):
            continue
        rc, cc = (int(round(rc_fc[idx, 0])), int(round(rc_fc[idx, 1])))
        rl, cl = (int(round(rc_fl[idx, 0])), int(round(rc_fl[idx, 1])))
        rr, cr = (int(round(rc_fr[idx, 0])), int(round(rc_fr[idx, 1])))
        if not (0 <= rc < h and 0 <= cc < w and (0 <= rl < h) and (0 <= cl < w) and (0 <= rr < h) and (0 <= cr < w)):
            continue
        if rc >= 252 and cc <= 165:
            continue
        pc = img_head[rc, cc].astype(float)
        pl = img_head[rl, cl].astype(float)
        pr = img_head[rr, cr].astype(float)
        if pc[0] > 170.0 and pc[1] > 120.0 and (pc[2] > 70.0):
            far_scores.append(pc[1] + pc[2] - 0.5 * (pl[1] + pl[2] + pr[1] + pr[2]))
    wood_far_score = float(np.mean(far_scores)) if len(far_scores) >= 4 else 0.0
    total = wood_near_score + 0.45 * max(0.0, wood_far_score) + 0.35 * stand_score
    return (total, best_d_stand)

def _detect_mallet_and_stand(robo, img_head, meta_head, xylo_exclusion):
    """Detect mallet pink spherical head, shaft unit vector u_shaft, and stand s_pos."""
    h, w, _ = img_head.shape
    r, g, b, _, sat, _, _, _ = _compute_hsv_and_stats(img_head)
    rows_grid, cols_grid = np.indices((h, w))
    roi = (rows_grid >= 95) & (rows_grid <= 400) & (cols_grid >= 35) & (cols_grid <= 605)
    roi &= ~xylo_exclusion
    roi &= ~((rows_grid >= 278) & (cols_grid <= 118))
    roi &= ~((rows_grid >= 248) & (cols_grid >= 468))
    pink_mask = roi & (r > 172.0) & (g < 102.0) & (b > 48.0) & (r - g > 95.0) & (r >= b - 15.0) & (sat > 0.45)
    comps = _connected_components(pink_mask, min_area=18)
    candidates = [c for c in comps if c['area'] <= 280]
    if not candidates:
        try:
            seg = robo.segment('the pink mallet head', camera='cam_head')
            if getattr(seg, 'found', False) and getattr(seg, 'centroid', None) is not None:
                cr, cc = seg.centroid
                candidates = [{'area': int(getattr(seg, 'area_px', 60) or 60), 'row': float(cr), 'col': float(cc)}]
        except Exception:
            pass
    best_info = None
    best_score = -1000000000.0
    for comp in candidates:
        m_pos_cand = _pixel_to_world_at_z(meta_head, comp['row'], comp['col'], _MALLET_HEAD_Z)
        if m_pos_cand is None:
            continue
        if not (-0.48 <= float(m_pos_cand[0]) <= 0.35 and -0.32 <= float(m_pos_cand[1]) <= 0.16):
            continue
        coarse_angles = np.linspace(-math.pi, math.pi, 240, endpoint=False)
        best_th = 0.0
        best_th_score = -1000000000.0
        best_d_stand = 0.1
        for th in coarse_angles:
            sc, d_st = _score_shaft_ray_in_head(img_head, meta_head, m_pos_cand, float(th))
            if sc > best_th_score:
                best_th_score = sc
                best_th = float(th)
                best_d_stand = d_st
        fine_angles = np.linspace(best_th - math.radians(4.0), best_th + math.radians(4.0), 55)
        for th in fine_angles:
            sc, d_st = _score_shaft_ray_in_head(img_head, meta_head, m_pos_cand, float(th))
            if sc > best_th_score:
                best_th_score = sc
                best_th = float(th)
                best_d_stand = d_st
        if best_th_score > best_score:
            best_score = best_th_score
            u_shaft = np.array([math.cos(best_th), math.sin(best_th), 0.0], dtype=float)
            s_pos = m_pos_cand + float(np.clip(best_d_stand, 0.075, 0.125)) * u_shaft
            best_info = {'m_pos': m_pos_cand, 'u_shaft': u_shaft, 's_pos': s_pos, 'head_row': float(comp['row']), 'head_col': float(comp['col']), 'score': best_th_score}
    if best_info is None or best_info['score'] < 22.0:
        return None
    return best_info

def _refine_grasp_with_wrist_cam(robo, m_pos_init, u_shaft_init, grasp_xy_init, arrived_yaw):
    """Use close-up cam_left_wrist at hover (0.35 mm/px) to refine shaft centerline and yaw."""
    try:
        img_w = robo.image('cam_left_wrist')
        meta_w = robo.camera_meta('cam_left_wrist')
    except Exception:
        return (grasp_xy_init, arrived_yaw, u_shaft_init)
    h, w, _ = img_w.shape
    arr = img_w.astype(float)
    r = arr[:, :, 0]
    g = arr[:, :, 1]
    b = arr[:, :, 2]
    gb = g + b
    wood_ok = (r > 175.0) & (g > 125.0) & (b > 75.0) & (r >= b)
    valid_rows = []
    valid_cols = []
    for row_idx in range(60, min(232, h - 20), 4):
        row_gb = gb[row_idx, :]
        row_wood = wood_ok[row_idx, :]
        best_c = None
        best_val = 45.0
        for col_idx in range(190, min(450, w - 45), 2):
            if np.mean(row_wood[col_idx - 8:col_idx + 9]) < 0.65:
                continue
            center_val = float(np.mean(row_gb[col_idx - 9:col_idx + 10]))
            bg_left = float(np.mean(row_gb[col_idx - 42:col_idx - 24]))
            bg_right = float(np.mean(row_gb[col_idx + 25:col_idx + 43]))
            contrast = center_val - 0.5 * (bg_left + bg_right)
            if contrast > best_val:
                best_val = contrast
                best_c = float(col_idx)
        if best_c is not None:
            valid_rows.append(float(row_idx))
            valid_cols.append(best_c)
    if len(valid_rows) < 12:
        return (grasp_xy_init, arrived_yaw, u_shaft_init)
    rows_arr = np.asarray(valid_rows, dtype=float)
    cols_arr = np.asarray(valid_cols, dtype=float)
    coeffs = np.polyfit(rows_arr, cols_arr, 1)
    pred_cols = coeffs[0] * rows_arr + coeffs[1]
    res = np.abs(cols_arr - pred_cols)
    inliers = res < max(3.5, float(np.median(res)) * 2.2)
    if int(np.sum(inliers)) < 10:
        return (grasp_xy_init, arrived_yaw, u_shaft_init)
    coeffs = np.polyfit(rows_arr[inliers], cols_arr[inliers], 1)
    slope, intercept = (float(coeffs[0]), float(coeffs[1]))
    if float(np.mean(np.abs(cols_arr[inliers] - (slope * rows_arr[inliers] + intercept)))) > 3.5:
        return (grasp_xy_init, arrived_yaw, u_shaft_init)
    p_top = _pixel_to_world_at_z(meta_w, 80.0, slope * 80.0 + intercept, float(m_pos_init[2]))
    p_bot = _pixel_to_world_at_z(meta_w, 210.0, slope * 210.0 + intercept, float(m_pos_init[2]))
    if p_top is None or p_bot is None:
        return (grasp_xy_init, arrived_yaw, u_shaft_init)
    vec_xy = (p_bot - p_top)[:2]
    norm_v = float(np.linalg.norm(vec_xy))
    if norm_v < 0.015:
        return (grasp_xy_init, arrived_yaw, u_shaft_init)
    u_wrist_2d = vec_xy / norm_v
    if float(np.dot(u_wrist_2d, u_shaft_init[:2])) < 0.0:
        u_wrist_2d = -u_wrist_2d
    ang_init = math.degrees(math.atan2(float(u_shaft_init[1]), float(u_shaft_init[0])))
    ang_wrist = math.degrees(math.atan2(float(u_wrist_2d[1]), float(u_wrist_2d[0])))
    delta_ang = _wrap_deg(ang_wrist - ang_init)
    if abs(delta_ang) > 10.0:
        return (grasp_xy_init, arrived_yaw, u_shaft_init)
    line_origin = p_top[:2]
    proj_len = float(np.dot(grasp_xy_init - line_origin, u_wrist_2d))
    grasp_xy_cand = line_origin + proj_len * u_wrist_2d
    if float(np.linalg.norm(grasp_xy_cand - grasp_xy_init)) > 0.015:
        return (grasp_xy_init, arrived_yaw, u_shaft_init)
    u_shaft_refined = np.array([float(u_wrist_2d[0]), float(u_wrist_2d[1]), 0.0], dtype=float)
    yaw_refined = _wrap_deg(float(arrived_yaw) + delta_ang)
    return (grasp_xy_cand, yaw_refined, u_shaft_refined)

def _detect_moved_pink_head(img_head_cur, img_head_0, meta_head, z_plane, expected_xy=None, max_radius_m=0.06):
    """Detect the lifted/held pink spherical mallet head in cam_head via color + frame difference."""
    h, w, _ = img_head_cur.shape
    r, g, b, _, sat, _, _, _ = _compute_hsv_and_stats(img_head_cur)
    diff = np.max(np.abs(img_head_cur.astype(float) - img_head_0.astype(float)), axis=2)
    rows_grid, cols_grid = np.indices((h, w))
    roi = (rows_grid >= 75) & (rows_grid <= 380) & (cols_grid >= 35) & (cols_grid <= 605)
    pink_moved = roi & (diff > 32.0) & (r > 175.0) & (g < 100.0) & (b > 50.0) & (r - g > 100.0) & (r >= b - 15.0) & (sat > 0.45)
    comps = _connected_components(pink_moved, min_area=16)
    best_pt = None
    best_dist = 1000000000.0
    for comp in comps:
        if comp['area'] > 260:
            continue
        pt_w = _pixel_to_world_at_z(meta_head, comp['row'], comp['col'], z_plane)
        if pt_w is None:
            continue
        if expected_xy is not None:
            dist = float(np.linalg.norm(pt_w[:2] - np.asarray(expected_xy, dtype=float)[:2]))
            if dist > max_radius_m:
                continue
            if dist < best_dist:
                best_dist = dist
                best_pt = (pt_w, float(comp['row']), float(comp['col']))
        else:
            return (pt_w, float(comp['row']), float(comp['col']))
    if best_pt is not None:
        return best_pt
    return (None, None, None)

def _preview_ok(robo, xyz, yaw, arm='left', pitch=90.0, roll=0.0, path='line'):
    try:
        pm = robo.preview_move([float(xyz[0]), float(xyz[1]), float(xyz[2])], arm=arm, pitch=float(pitch), yaw=float(yaw), roll=float(roll), path=path)
    except Exception:
        return False
    if isinstance(pm, dict):
        return bool(pm.get('reachable')) and (not pm.get('ik_error')) and (not pm.get('note'))
    return bool(getattr(pm, 'reachable', getattr(pm, 'reached', False))) and (not getattr(pm, 'ik_error', None)) and (not getattr(pm, 'note', None))

def _safe_move(robo, xyz, *, arm='left', gripper, pitch=90.0, yaw, roll=0.0, path='line'):
    st = robo.state()
    if getattr(st, 'truncated', False):
        return None
    try:
        return robo.move_to([float(xyz[0]), float(xyz[1]), float(xyz[2])], arm=arm, gripper=gripper, pitch=float(pitch), yaw=float(yaw), roll=float(roll), path=path)
    except Exception as exc:
        if exc.__class__.__name__ == 'EpisodeFinished' or 'truncated' in str(exc).lower():
            return None
        raise

def _safe_gripper(robo, arm, action):
    st = robo.state()
    if getattr(st, 'truncated', False):
        return None
    try:
        return robo.set_gripper(arm, action)
    except Exception as exc:
        if exc.__class__.__name__ == 'EpisodeFinished' or 'truncated' in str(exc).lower():
            return None
        raise

def _move_hover_with_fallback(robo, xyz, *, gripper, yaw):
    """Move to a high-altitude hover waypoint, falling back if straight line fails."""
    res = _safe_move(robo, xyz, gripper=gripper, yaw=yaw, path='line')
    if res is None or getattr(res, 'truncated', False) or getattr(robo.state(), 'truncated', False):
        return res
    if getattr(res, 'reached', False):
        return res
    cur_tcp = np.asarray(robo.state().left.tcp_pos, dtype=float)
    mid_xyz = [0.5 * (float(cur_tcp[0]) + float(xyz[0])), min(float(cur_tcp[1]), float(xyz[1])) - 0.02, max(float(cur_tcp[2]), float(xyz[2]))]
    cur_yaw = float(robo.state().left.yaw)
    mid_yaw = _wrap_deg(cur_yaw + 0.5 * _wrap_deg(float(yaw) - cur_yaw))
    if _preview_ok(robo, mid_xyz, mid_yaw, path='line'):
        res_mid = _safe_move(robo, mid_xyz, gripper=gripper, yaw=mid_yaw, path='line')
        if res_mid is None or getattr(res_mid, 'truncated', False) or getattr(robo.state(), 'truncated', False):
            return res_mid
        res = _safe_move(robo, xyz, gripper=gripper, yaw=yaw, path='line')
        if res is None or getattr(res, 'truncated', False) or getattr(robo.state(), 'truncated', False):
            return res
        if getattr(res, 'reached', False):
            return res
    return _safe_move(robo, xyz, gripper=gripper, yaw=yaw, path='auto')

def _grasp_and_lift_mallet(robo, mallet_info, img_head_0, meta_head, d_grasp_pref=None):
    """Grasp the mallet shaft clear of the stand, lift it, and verify from observable evidence."""
    m_pos_init = np.asarray(mallet_info['m_pos'], dtype=float)
    u_shaft = np.asarray(mallet_info['u_shaft'], dtype=float)
    s_pos = np.asarray(mallet_info['s_pos'], dtype=float)
    default_d = float(np.clip(0.791 * _SHAFT_YMAX_DEFAULT, 0.145, 0.165))
    cand_ds = [d_grasp_pref] if d_grasp_pref is not None else []
    cand_ds.extend([default_d, 0.155, 0.165, 0.145, 0.135, 0.055])
    z_hover_grasp = float(m_pos_init[2]) + 0.072
    z_desc_grasp = float(m_pos_init[2]) + 0.0026
    z_lift_grasp = float(m_pos_init[2]) + 0.0676
    beat_dir_deg = math.degrees(math.atan2(-float(u_shaft[1]), -float(u_shaft[0])))
    chosen_grasp_yaw = _wrap_deg(beat_dir_deg + 90.0)
    d_grasp = default_d
    grasp_xy = m_pos_init[:2] + d_grasp * u_shaft[:2]
    for cand_d in cand_ds:
        if cand_d is None:
            continue
        cand_xy = m_pos_init[:2] + float(cand_d) * u_shaft[:2]
        if float(np.linalg.norm(cand_xy - s_pos[:2])) < 0.035:
            continue
        found_yaw = False
        for sign in (1.0, -1.0):
            cand_yaw = _wrap_deg(beat_dir_deg + sign * 90.0)
            if _preview_ok(robo, [cand_xy[0], cand_xy[1], z_hover_grasp], cand_yaw, path='auto') and _preview_ok(robo, [cand_xy[0], cand_xy[1], z_desc_grasp], cand_yaw, path='auto'):
                d_grasp = float(cand_d)
                grasp_xy = cand_xy
                chosen_grasp_yaw = cand_yaw
                found_yaw = True
                break
        if found_yaw:
            break
    res_hover = _move_hover_with_fallback(robo, [grasp_xy[0], grasp_xy[1], z_hover_grasp], gripper=robo.OPEN, yaw=chosen_grasp_yaw)
    if res_hover is None or getattr(res_hover, 'truncated', False) or getattr(robo.state(), 'truncated', False):
        return (False, d_grasp, None)
    arrived_yaw = float(robo.state().left.yaw)
    grasp_xy, arrived_yaw, u_shaft = _refine_grasp_with_wrist_cam(robo, m_pos_init, u_shaft, grasp_xy, arrived_yaw)
    beat_dir_deg = math.degrees(math.atan2(-float(u_shaft[1]), -float(u_shaft[0])))
    res_desc = _safe_move(robo, [grasp_xy[0], grasp_xy[1], z_desc_grasp], gripper=robo.OPEN, yaw=arrived_yaw, path='line')
    if res_desc is None or getattr(res_desc, 'truncated', False) or getattr(robo.state(), 'truncated', False):
        return (False, d_grasp, None)
    tcp_desc_z = float(robo.state().left.tcp_pos[2])
    res_grip = _safe_gripper(robo, 'left', robo.CLOSE)
    if res_grip is None or getattr(res_grip, 'truncated', False) or getattr(robo.state(), 'truncated', False):
        return (False, d_grasp, None)
    res_lift = _safe_move(robo, [grasp_xy[0], grasp_xy[1], z_lift_grasp], gripper=robo.CLOSE, yaw=arrived_yaw, path='line')
    if res_lift is None or getattr(res_lift, 'truncated', False) or getattr(robo.state(), 'truncated', False):
        return (False, d_grasp, None)
    st_lift = robo.state()
    if float(st_lift.left.gripper) <= 0.01:
        return (False, d_grasp, None)
    tcp_lift = np.asarray(st_lift.left.tcp_pos, dtype=float)
    cur_yaw = float(st_lift.left.yaw)
    lift_dz = max(0.04, float(tcp_lift[2]) - tcp_desc_z)
    kin_offset_xy = m_pos_init[:2] - grasp_xy
    kin_r_len = float(np.linalg.norm(kin_offset_xy))
    if not 0.05 <= kin_r_len <= 0.22:
        kin_r_len = float(d_grasp)
    kin_ang = _wrap_deg(beat_dir_deg + _wrap_deg(cur_yaw - arrived_yaw))
    expected_head_xy = tcp_lift[:2] + kin_r_len * np.array([math.cos(math.radians(kin_ang)), math.sin(math.radians(kin_ang))], dtype=float)
    r_len = kin_r_len
    cur_ang = kin_ang
    try:
        img_lift = robo.image('cam_head')
        m_lift_pt, row_lift, _ = _detect_moved_pink_head(img_lift, img_head_0, meta_head, float(m_pos_init[2]) + lift_dz, expected_xy=expected_head_xy, max_radius_m=0.045)
        if m_lift_pt is not None and row_lift is not None:
            if float(mallet_info['head_row']) - float(row_lift) >= 5.0:
                vis_off = (m_lift_pt - tcp_lift)[:2]
                vis_r = float(np.linalg.norm(vis_off))
                if 0.08 <= vis_r <= 0.21:
                    r_len = 0.5 * kin_r_len + 0.5 * vis_r
                    vis_ang = math.degrees(math.atan2(float(vis_off[1]), float(vis_off[0])))
                    if abs(_wrap_deg(vis_ang - kin_ang)) <= 12.0:
                        cur_ang = _wrap_deg(kin_ang + 0.5 * _wrap_deg(vis_ang - kin_ang))
    except Exception:
        pass
    return (True, d_grasp, {'r_len': r_len, 'cur_ang': cur_ang, 'cur_yaw': cur_yaw})

def _select_post_lift_strike_plan(robo, cur_yaw, cur_ang, r_len, xylo_info):
    """Select target gripper yaw and XY offset after lifting the mallet."""
    b0_center, hit0_z = _get_key_target_xyz(xylo_info, 0)
    b3_center, _ = _get_key_target_xyz(xylo_info, 3)
    b7_center, _ = _get_key_target_xyz(xylo_info, 7)
    z_hover = hit0_z + 0.0665
    z_dip = hit0_z + 0.0251
    joints = robo.state().left.joints
    j0_lift = float(joints[0])
    j5_lift = float(joints[5])
    fallback_choice = None
    for beat_target_deg in (cur_ang,):
        delta_yaw_deg = _wrap_deg(beat_target_deg - cur_ang)
        cand_target_yaw = _wrap_deg(cur_yaw + delta_yaw_deg)
        beat_rad = math.radians(beat_target_deg)
        off_xy_cand = r_len * np.array([math.cos(beat_rad), math.sin(beat_rad)], dtype=float)
        tcp0 = b0_center[:2] - off_xy_cand
        tcp3 = b3_center[:2] - off_xy_cand
        tcp7 = b7_center[:2] - off_xy_cand
        j0_0 = math.atan2(-(float(tcp0[0]) + 0.3), float(tcp0[1]) + 0.45)
        j0_7 = math.atan2(-(float(tcp7[0]) + 0.3), float(tcp7[1]) + 0.45)
        delta_yaw_rad = math.radians(delta_yaw_deg)
        j5_0 = j5_lift + (j0_0 - j0_lift) - delta_yaw_rad
        j5_7 = j5_lift + (j0_7 - j0_lift) - delta_yaw_rad
        if max(abs(j5_0), abs(j5_7)) > 2.95:
            continue
        poses_ok = _preview_ok(robo, [tcp0[0], tcp0[1], z_hover], cand_target_yaw, path='auto') and _preview_ok(robo, [tcp0[0], tcp0[1], z_dip], cand_target_yaw, path='auto') and _preview_ok(robo, [tcp3[0], tcp3[1], z_hover], cand_target_yaw, path='auto') and _preview_ok(robo, [tcp3[0], tcp3[1], z_dip], cand_target_yaw, path='auto') and _preview_ok(robo, [tcp7[0], tcp7[1], z_hover], cand_target_yaw, path='auto') and _preview_ok(robo, [tcp7[0], tcp7[1], z_dip], cand_target_yaw, path='auto')
        if not poses_ok:
            continue
        if fallback_choice is None:
            fallback_choice = (cand_target_yaw, off_xy_cand)
        if _preview_ok(robo, [tcp0[0], tcp0[1], z_hover], cand_target_yaw, path='line'):
            return (cand_target_yaw, off_xy_cand)
    if fallback_choice is not None:
        return fallback_choice
    default_delta = _wrap_deg(25.0 - cur_ang)
    default_yaw = _wrap_deg(cur_yaw + default_delta)
    default_rad = math.radians(25.0)
    default_off = r_len * np.array([math.cos(default_rad), math.sin(default_rad)], dtype=float)
    return (default_yaw, default_off)

def run(robo):
    """Execute the policy for play_Xylophone."""
    if getattr(robo.state(), 'truncated', False):
        return
    img_head_0 = robo.image('cam_head').copy()
    meta_head = robo.camera_meta('cam_head')
    xylo_info = _detect_xylophone(robo, img_head_0, meta_head)
    if xylo_info is None:
        return
    mallet_info = _detect_mallet_and_stand(robo, img_head_0, meta_head, xylo_info['xylo_exclusion'])
    if mallet_info is None:
        return
    lifted_ok, d_grasp, lift_meas = _grasp_and_lift_mallet(robo, mallet_info, img_head_0, meta_head)
    if not lifted_ok and (not getattr(robo.state(), 'truncated', False)):
        for retry_d in (0.145, 0.16):
            if getattr(robo.state(), 'truncated', False):
                return
            if _safe_gripper(robo, 'left', robo.OPEN) is None:
                return
            img_retry = robo.image('cam_head').copy()
            meta_retry = robo.camera_meta('cam_head')
            mallet_retry = _detect_mallet_and_stand(robo, img_retry, meta_retry, xylo_info['xylo_exclusion'])
            if mallet_retry is not None:
                mallet_info = mallet_retry
                img_head_0 = img_retry
                meta_head = meta_retry
            lifted_ok, d_grasp, lift_meas = _grasp_and_lift_mallet(robo, mallet_info, img_head_0, meta_head, d_grasp_pref=retry_d)
            if lifted_ok:
                break
    if not lifted_ok or lift_meas is None or getattr(robo.state(), 'truncated', False):
        return
    cur_yaw = float(lift_meas['cur_yaw'])
    cur_ang = float(lift_meas['cur_ang'])
    r_len = float(lift_meas['r_len'])
    if not 0.05 <= r_len <= 0.22:
        r_len = float(d_grasp)
    chosen_target_yaw, expected_off_xy = _select_post_lift_strike_plan(robo, cur_yaw, cur_ang, r_len, xylo_info)
    off_xy = expected_off_xy.copy()
    for k in range(8):
        if getattr(robo.state(), 'truncated', False):
            return
        b_center, key_hit_z = _get_key_target_xyz(xylo_info, k)
        z_hover = key_hit_z + 0.0692
        z_dip = key_hit_z + 0.0221
        tcp_xy = b_center[:2] - off_xy
        res_hi = _move_hover_with_fallback(robo, [tcp_xy[0], tcp_xy[1], z_hover], gripper=robo.CLOSE, yaw=chosen_target_yaw)
        if res_hi is None or getattr(res_hi, 'truncated', False) or getattr(robo.state(), 'truncated', False):
            return
        res_lo = _safe_move(robo, [tcp_xy[0], tcp_xy[1], z_dip], gripper=robo.CLOSE, yaw=chosen_target_yaw, path='line')
        if res_lo is None or getattr(res_lo, 'truncated', False) or getattr(robo.state(), 'truncated', False):
            return
        if k == 7 and (not getattr(robo.state(), 'truncated', False)):
            res_lo2 = _safe_move(robo, [tcp_xy[0], tcp_xy[1], key_hit_z + 0.0221], gripper=robo.CLOSE, yaw=chosen_target_yaw, path='line')
            if res_lo2 is None or getattr(res_lo2, 'truncated', False) or getattr(robo.state(), 'truncated', False):
                return
        if k < 7 or not getattr(robo.state(), 'truncated', False):
            res_up = _safe_move(robo, [tcp_xy[0], tcp_xy[1], z_hover], gripper=robo.CLOSE, yaw=chosen_target_yaw, path='line')
            if res_up is None or getattr(res_up, 'truncated', False) or getattr(robo.state(), 'truncated', False):
                return
            if _preview_ok(robo, [tcp_xy[0], tcp_xy[1], z_hover + 0.015], chosen_target_yaw, path='line'):
                res_up2 = _safe_move(robo, [tcp_xy[0], tcp_xy[1], z_hover + 0.015], gripper=robo.CLOSE, yaw=chosen_target_yaw, path='line')
                if res_up2 is None or getattr(res_up2, 'truncated', False) or getattr(robo.state(), 'truncated', False):
                    return
            if k in (0, 1, 2, 3, 4):
                try:
                    st_up = robo.state()
                    tcp_up = np.asarray(st_up.left.tcp_pos, dtype=float)
                    if abs(_wrap_deg(float(st_up.left.yaw) - chosen_target_yaw)) < 6.0:
                        img_up = robo.image('cam_head')
                        m_up_pt, _, _ = _detect_moved_pink_head(img_up, img_head_0, meta_head, float(tcp_up[2]) - 0.005, expected_xy=tcp_up[:2] + off_xy, max_radius_m=0.022)
                        if m_up_pt is not None:
                            meas_off = (m_up_pt - tcp_up)[:2]
                            if 0.12 <= float(np.linalg.norm(meas_off)) <= 0.19 and float(np.linalg.norm(meas_off - expected_off_xy)) <= 0.016:
                                off_xy = 0.7 * off_xy + 0.3 * meas_off
                except Exception:
                    pass
